{"recursos":[
 {"id":"parte","ruta":"${nombre}/parte.txt","contenido":"Depósito ${ciudad}: ${bultos} bultos por día"},
 {"id":"turnos","ruta":"${nombre}/turnos.txt","contenido":"Turno mañana y tarde en ${ciudad}"}]}

def planear():
    est, des, acc = leer_estado(), deseado(), []
    for d, r in sorted(des.items()):
        e = est["recursos"].get(d); vivo = real(r["ruta"])
        if e is None: acc.append(("crear", d, "no está en el estado"))
        elif vivo is None: acc.append(("crear", d, "DERIVA: el archivo desapareció"))
        elif sha(vivo) != e["sha"]: acc.append(("actualizar", d, "DERIVA: alguien lo cambió a mano (%s -> %s)" % (e["sha"], sha(vivo))))
        elif e["contenido"] != r["contenido"] or e["ruta"] != r["ruta"]: acc.append(("actualizar", d, "cambió la configuración"))
    for d in sorted(set(est["recursos"]) - set(des)):
        acc.append(("destruir", d, "ya no está en la configuración"))
    return est, des, acc
